import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:sizer/sizer.dart';import 'package:smart_coach_new/core/widgets/custom_button.dart';import 'package:smart_coach_new/core/widgets/dialogs/custom_dialog_border_radius_view.dart';class CommonYesNoDialog extends StatelessWidget {  final String? title;  final String message;  final String positiveButtonText;  final String negativeButtonText;  final VoidCallback? onYes;  final VoidCallback? onCancel;  const CommonYesNoDialog({    super.key,    this.title,    required this.message,    required this.positiveButtonText,    required this.negativeButtonText,    this.onYes,    this.onCancel,  });  @override  Widget build(BuildContext context) {    return CustomDialogBorderRadiusView(      child: Column(        mainAxisSize: MainAxisSize.min,        crossAxisAlignment: CrossAxisAlignment.start,        children: [          if (title != null)            Text(              title!,              style: TextStyle(                fontSize: 14.sp,                fontWeight: FontWeight.w500,              ),            ),          if (title != null)            SizedBox(              height: 1.h,            ),          Text(            message,            style: TextStyle(              fontSize: 13.sp,              fontWeight: FontWeight.w400,            ),          ),          SizedBox(height: 2.h),          Row(            mainAxisAlignment: MainAxisAlignment.end,            children: [              CustomButton(                text: negativeButtonText,                color: const Color(0xFFF2F3F5),                textColor: Colors.black,                textSize: 12,                padding: EdgeInsets.symmetric(                  vertical: 1.6.h,                  horizontal: 5.w,                ),                radius: 6,                onPressed: () {                  context.pop();                  onCancel?.call();                },              ),              SizedBox(width: 3.w),              CustomButton(                text: positiveButtonText,                padding: EdgeInsets.symmetric(                  vertical: 1.6.h,                  horizontal: 5.w,                ),                textSize: 12,                radius: 6,                onPressed: () {                  context.pop();                  onYes?.call();                },              ),            ],          ),        ],      ),    );  }}